function validate([n, target]) {
  if (!Number.isInteger(n) || n < 1 || n > 1e12) return 'n is a whole number from 1 to 10^12.';
  if (!Number.isInteger(target) || target < 1 || target > 150) return 'target is a whole number from 1 to 150.';
  return null;
}

