function makeIntegerBeautiful(n, target) {
  const digitSum = (value) => {
    let sum = 0;
    while (value > 0) {
      sum += value % 10;
      value = Math.floor(value / 10);
    }
    return sum;
  };

  let current = n;
  let place = 1;
  while (digitSum(current) > target) {
    place *= 10;
    const remainder = current % place;
    if (remainder > 0) {
      current += place - remainder;
    }
  }
  return current - n;
}

