function makeIntegerBeautiful(n, target) {
  const sumOf = (text) => [...text].reduce((total, d) => total + Number(d), 0);
  // Try every x directly while that stays cheap.
  for (let x = 0; x <= 20000; x++) if (sumOf(String(n + x)) <= target) return x;
  // Otherwise the answer is n rounded up at some digit: keep a prefix, add one to it, and pad with zeros.
  const digits = String(n);
  let best = null;
  for (let keep = 0; keep <= digits.length; keep++) {
    const prefix = keep === 0 ? 0n : BigInt(digits.slice(0, keep));
    const candidate = keep === digits.length ? BigInt(n) : (prefix + 1n) * 10n ** BigInt(digits.length - keep);
    if (candidate >= BigInt(n) && sumOf(String(candidate)) <= target && (best === null || candidate < best)) best = candidate;
  }
  return Number(best - BigInt(n));
}

