function generate(rand, size) {
  const digitSum = (v) => [...String(v)].reduce((t, d) => t + Number(d), 0);
  let n;
  const shape = rand();
  if (size === 'small' && shape < 0.5) n = 1 + Math.floor(rand() * 9999);
  else {
    // Build a number of up to 12 digits, often heavy with nines so that carries ripple.
    const length = size === 'large' ? 12 : 1 + Math.floor(rand() * 12);
    const nines = rand();
    let text = String(1 + Math.floor(rand() * 9));
    while (text.length < length) text += rand() < nines ? '9' : String(Math.floor(rand() * 10));
    n = Number(text);
  }
  if (rand() < 0.08) n = 1e12;
  const target = 1 + Math.floor(rand() * Math.min(150, digitSum(n) + 2));
  return [n, target];
}
